"use strict";
// FAKE_INTEGRATION: real application/Resolver/PostgreSQL provider over isolated
// PGlite; Understanding is a model double. Expected guest text is independently
// specified by the approved product contract, never generated by the composer.
const { test } = require("node:test");
const assert = require("node:assert/strict");
const { run, formalProviders } = require("./new-core-inventory-unknown-outcome-runner");
const { createMvpService } = require("../lib/mvp-service");
const { validateComposedSection } = require("../lib/conversation-engine-v2/controlled-composer");
const NOW = "2026-09-19T03:00:00.000Z";
const cases = [
  { message: "今天有房嗎", raw: "今天", kind: "relative_date", offset: 0, date: "2026-09-19", out: "2026-09-20", closed: "2026-09-19 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "後天有房嗎", raw: "後天", kind: "relative_date", offset: 2, date: "2026-09-21", out: "2026-09-22", closed: "2026-09-21 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "9/28有房嗎", raw: "9/28", date: "2026-09-28", out: "2026-09-29", closed: "2026-09-28 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "11/25有房嗎", raw: "11/25", date: "2026-11-25", out: "2026-11-26", closed: "2026-11-25 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "12/25有房嗎", raw: "12/25", date: "2026-12-25", out: "2026-12-26", closed: "2026-12-25 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "2027/1/2有房嗎", raw: "2027/1/2", date: "2027-01-02", out: "2027-01-03", closed: "2027-01-02 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "11/25~11/27 401房，還有嗎？", raw: "11/25~11/27", date: "2026-11-25", out: "2026-11-27", room: true, nights: 2, closed: "2026-11-25 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "9/30到10/2可以預訂嗎", raw: "9/30到10/2", date: "2026-09-30", out: "2026-10-02", nights: 2, closed: "2026-09-30 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" },
  { message: "12/31到2027/1/2可以預訂嗎", raw: "12/31到2027/1/2", date: "2026-12-31", out: "2027-01-02", nights: 2, closed: "2026-12-31 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。" }
];
for (const status of ["missing", "closed", "available"]) for (const c of cases) {
  test(`final guest text retains official date and inventory: ${status}/${c.message}`, async () => {
    const { providers } = await formalProviders();
    const service = createMvpService(providers, { now: () => new Date(NOW) });
    if (status !== "missing") service.applyBatch({ customerId: "inventory-a", mode: "all_inventory", startDate: c.date,
      endDate: new Date(Date.parse(c.out) - 86400000).toISOString().slice(0, 10), status });
    const r = await run({ now: NOW, date: c.date, availabilityProvider: providers.availability,
      requests: [{ capability: "availability", kind: c.room ? "room" : "property", identity: c.room ? "product-a" : null, text: c.message,
        temporal: { rawText: c.raw, kind: c.kind || (c.nights ? "date_range" : "absolute_date"),
          checkInCandidate: c.kind ? null : c.date, checkOutCandidate: c.nights ? c.out : null, nightsCandidate: c.nights || null,
          ...(c.kind ? { relativeSemantics: { dayOffset: c.offset, dayPeriod: "unspecified" } } : {}) } }] });
    assert.equal(r.artifacts.canonicalItems[0].canonicalRequest.temporalState.checkIn, c.date);
    assert.equal(r.artifacts.canonicalItems[0].canonicalRequest.temporalState.checkOut, c.out);
    assert.equal(r.finalResponse.action, "reply");
    assert.equal(r.finalResponse.shouldReply, true);
    const text = r.finalResponse.replyText;
    assert.ok(text.includes(c.date), "the final guest-visible text must retain the resolved check-in date");
    for (const forbidden of ["missing", "unknown", "房況資料尚未完整", "目前無法確認", "請稍後再試", "直接與我們聯繫"]) {
      assert.ok(!text.includes(forbidden), `guest text contains forbidden response: ${forbidden}`);
    }
    if (status !== "available") {
      assert.equal(text, c.closed + "\n查房連結：https://example.invalid/inventorya");
      assert.equal(r.artifacts.executionOutcomes[0].outcome, status === "missing" ? "unknown" : "no_availability");
      if (status === "missing") assert.equal(r.artifacts.executionOutcomes[0].reason, "missing_inventory_records");
    } else {
      // Hand-checked fixture: each formally offered product costs 1,000/night;
      // the explicit room query must not include the other bundle product.
      const roomPrice = c.nights === 2 ? "Garden lodging共 2,000 元。" : "Garden lodging共 1,000 元。";
      const bundlePrice = c.nights === 2 ? "Courtyard group共 2,000 元。" : "Courtyard group共 1,000 元。";
      assert.equal(text, c.date + " 入住\n目前可預訂。\n" + roomPrice + (c.room ? "" : "\n" + bundlePrice)
        + "\n查房連結：https://example.invalid/inventorya");
      assert.equal(r.artifacts.executionOutcomes[0].outcome, "answered");
    }
  });
}

// UNIT_TEST: changing composer output must not redefine validation truth.
const closedSection = { type: "availability", status: "answered", responseMode: "answer", claimType: "FACTUAL_ANSWER",
  outcomeStatus: "no_availability", facts: { checkIn: "2026-09-21", checkOut: "2026-09-22", availableInventory: [], source: "availability_resolver" } };
for (const text of [
  "您查詢的日期目前沒有可提供的房型，歡迎查看其他日期，謝謝您。",
  "2026-09-19 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。",
  "謝謝您的詢問，請稍後再試，或直接與我們聯繫。"
]) test(`independent final-text contract rejects: ${text}`, () => {
  assert.equal(validateComposedSection(closedSection, text).ok, false);
});
test("independent final-text contract accepts the approved dated closed response", () => {
  assert.equal(validateComposedSection(closedSection, "2026-09-21 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。").ok, true);
});

test("changing the renderer cannot make its missing-date output validate itself", () => {
  // Mutate only an isolated in-memory module; no production file/cache change.
  const fs = require("node:fs"), Module = require("node:module"), path = require("node:path");
  const filename = require.resolve("../lib/conversation-engine-v2/controlled-composer");
  const source = fs.readFileSync(filename, "utf8");
  const original = 'return `${facts.checkIn} 入住目前沒有可提供的房型，歡迎查看其他日期，謝謝您。`;';
  assert.ok(source.includes(original), "the mutation must hit the active closed renderer");
  const mutant = new Module(filename, module);
  mutant.filename = filename; mutant.paths = Module._nodeModulePaths(path.dirname(filename));
  mutant._compile(source.replace(original, 'return "您查詢的日期目前沒有可提供的房型，歡迎查看其他日期，謝謝您。";'), filename);
  const wrong = mutant.exports.composeSection(closedSection);
  assert.equal(wrong, "您查詢的日期目前沒有可提供的房型，歡迎查看其他日期，謝謝您。");
  assert.equal(mutant.exports.validateComposedSection(closedSection, wrong).ok, false);
});

const offeredSection = { type: "availability", status: "answered", responseMode: "answer", claimType: "FACTUAL_ANSWER", outcomeStatus: "answered",
  facts: { source: "availability_resolver", checkIn: "2026-09-28", availability: "available",
    prices: [{ inventory: { publicName: "Garden lodging" }, total: 1000, currency: "TWD" }] } };
for (const text of [
  "2026-09-28 入住\n目前可預訂。\nGarden lodging共 2,000 元。",
  "2026-09-28 入住\n目前可預訂。\nDifferent room共 1,000 元。",
  "2026-09-28 入住\n目前可預訂。",
  "2026-09-19 入住\n目前可預訂。\nGarden lodging共 1,000 元。"
]) test(`independent offered-room contract rejects altered date/room/price: ${text}`, () => {
  assert.equal(validateComposedSection(offeredSection, text).ok, false);
});
